begin;
create table if not exists public.bv_news_subscriptions(user_id uuid primary key references auth.users(id) on delete cascade, active boolean not null default false, token uuid not null default gen_random_uuid(), updated_at timestamptz not null default now());
create table if not exists public.bv_news_jobs(id uuid primary key default gen_random_uuid(), period text not null check(period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'), mode text not null check(mode in ('preview','test','send')), requested_by uuid default auth.uid(), state text not null default 'queued', detail text, html text, created_at timestamptz default now());
create table if not exists public.bv_news_delivery(period text not null,user_id uuid not null,state text not null, detail text, created_at timestamptz default now(),primary key(period,user_id));
alter table public.bv_news_subscriptions enable row level security;
alter table public.bv_news_jobs enable row level security;
alter table public.bv_news_delivery enable row level security;
revoke all on public.bv_news_subscriptions,public.bv_news_jobs,public.bv_news_delivery from anon,authenticated;
create or replace function public.bv_news_subscribe(enabled boolean) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or not public.bv_member() then raise exception 'Members only'; end if; insert into public.bv_news_subscriptions(user_id,active) values(auth.uid(),enabled) on conflict(user_id) do update set active=excluded.active,updated_at=now(); end $$;
create or replace function public.bv_news_status() returns boolean language sql security definer set search_path='' as $$ select coalesce((select active from public.bv_news_subscriptions where user_id=auth.uid()),false) $$;
create or replace function public.bv_news_unsubscribe(code uuid) returns void language sql security definer set search_path='' as $$ update public.bv_news_subscriptions set active=false,updated_at=now() where token=code $$;
create or replace function public.bv_news_request(p text,m text) returns uuid language plpgsql security definer set search_path='' as $$ declare j uuid; begin if not public.bv_admin() then raise exception 'Admins only'; end if; insert into public.bv_news_jobs(period,mode) values(p,m) returning id into j; return j; end $$;
create or replace function public.bv_news_recipients() returns table(user_id uuid,email text,token uuid) language sql security definer set search_path='' as $$ select s.user_id,u.email,s.token from public.bv_news_subscriptions s join auth.users u on u.id=s.user_id join public.club_members m on m.email=lower(u.email) where s.active and u.email_confirmed_at is not null $$;
create or replace function public.bv_news_counts(start_at timestamptz,end_at timestamptz) returns jsonb language sql security definer set search_path='' as $$ select jsonb_build_object('new_members',(select count(*) from auth.users u join public.club_members m on m.email=lower(u.email) where u.created_at>=start_at and u.created_at<end_at and u.email_confirmed_at is not null),'new_files',(select count(*) from storage.objects where bucket_id='bookclub-files' and created_at>=start_at and created_at<end_at)) $$;
create or replace function public.bv_news_admin_email(uid uuid) returns text language sql security definer set search_path='' as $$ select u.email from auth.users u join public.club_admins a on a.email=lower(u.email) where u.id=uid and u.email_confirmed_at is not null $$;
revoke all on function public.bv_news_subscribe(boolean),public.bv_news_status(),public.bv_news_unsubscribe(uuid),public.bv_news_request(text,text),public.bv_news_recipients(),public.bv_news_counts(timestamptz,timestamptz),public.bv_news_admin_email(uuid) from public;
grant execute on function public.bv_news_subscribe(boolean),public.bv_news_status(),public.bv_news_request(text,text) to authenticated;
grant execute on function public.bv_news_unsubscribe(uuid) to anon,authenticated;
grant execute on function public.bv_news_recipients(),public.bv_news_counts(timestamptz,timestamptz),public.bv_news_admin_email(uuid) to service_role;
grant select on public.bv_news_jobs,public.bv_news_delivery to authenticated;
grant all on public.bv_news_jobs,public.bv_news_delivery to service_role;
drop policy if exists news_admin_jobs on public.bv_news_jobs;
create policy news_admin_jobs on public.bv_news_jobs for select to authenticated using(public.bv_admin());
drop policy if exists news_admin_delivery on public.bv_news_delivery;
create policy news_admin_delivery on public.bv_news_delivery for select to authenticated using(public.bv_admin());
commit;
